import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
import { useUiCopy } from 'app/hooks/useUiCopy';

type ZimmSearchInputProps = {
  /** Forwarded to the native input for programmatic focus control. */
  inputRef?: React.Ref<HTMLInputElement>;
  /** Placeholder text shown in the default state. Rendered uppercase via CSS. Defaults to
   *  useUiCopy()'s `header.field.placeholder.search` entry when omitted. */
  placeholder?: string;
};

/**
 * Search input atom — 180×24px underline-style field.
 *
 * Default state: placeholder "SEARCH" label with bottom border.
 * Active state (has value): typed text + clear (×) button positioned absolutely.
 *
 * Adapts core search behaviour from the base SFCC Search component:
 *   - Navigates to the search results page on Enter (useNavigation + searchUrlBuilder).
 *   - Saves the submitted term to session recent-search history (capped at RECENT_SEARCH_LIMIT).
 *   - Clear (×) button resets the field without submitting.
 *   - Suggestions UI (useSearchSuggestions popover) is Sprint 3 work — Squad B scope.
 *
 * Figma: nodes 40000259:10763 (default), 40000259:13094 (active),
 *        40000259:13091 (clear icon, 16×16px at right edge).
 *
 * @param props.inputRef - Forwarded to the native input for programmatic focus.
 * @param props.placeholder - Placeholder text; rendered uppercase via CSS.
 */
export const ZimmSearchInput = ({ inputRef, placeholder }: ZimmSearchInputProps) => {
  const styles = useMultiStyleConfig('ZimmSearchInput');
  const [value, setValue] = useState('');
  const navigate = useNavigation();
  const { t } = useUiCopy();
  const resolvedPlaceholder = placeholder ?? t('header.field.placeholder.search', 'Search');

  const saveRecentSearch = (searchText: string) => {
    // getSessionJSONItem returns whatever JSON currently sits under the key — validate the
    // shape rather than asserting it, so a corrupted or unexpected stored value can't throw
    // here (see .filter/.toLowerCase below).
    const stored: unknown = getSessionJSONItem(RECENT_SEARCH_KEY);
    const current = Array.isArray(stored) ? stored.filter((s): s is string => typeof s === 'string') : [];
    const deduped = current.filter((s) => s.toLowerCase() !== searchText.toLowerCase());
    setSessionJSONItem(RECENT_SEARCH_KEY, [searchText, ...deduped].slice(0, RECENT_SEARCH_LIMIT));
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const searchText = value.trim();
    if (!searchText) return;
    saveRecentSearch(searchText);
    navigate(searchUrlBuilder(searchText));
  };
